"""Normalize text captured from agent transcripts: drop harness noise, keep what people said."""

from __future__ import annotations

import re

MAX_CHARS = 20_000

# Whole messages that are tool/harness plumbing rather than conversation.
_NOISE_PREFIXES = (
    "<task-notification>",
    "[Request interrupted",
    "This session is being continued from a previous conversation",
    "<bash-stdout>",
    "<bash-stderr>",
    "<local-command-stdout>",
    "<local-command-stderr>",
    "<local-command-caveat>",
    "Caveat: The messages below were generated by the user while running local commands",
    "<environment_context>",
    "<user_instructions>",
    "# AGENTS.md instructions",
    "<turn_aborted>",
)

_SYSTEM_BLOCK = re.compile(
    r"<(system-reminder|system_instruction|context_window_[\w-]*)>.*?</\1>", re.DOTALL
)
_PASTED = re.compile(r"</?pasted_content[^>]*>")
_COMMAND = re.compile(
    r"<command-name>(?P<name>.*?)</command-name>.*?(?:<command-args>(?P<args>.*?)</command-args>)?",
    re.DOTALL,
)
_BASH_INPUT = re.compile(r"<bash-input>(.*?)</bash-input>", re.DOTALL)


def clean_text(text: str) -> str:
    """Return the human-meaningful part of a message, or "" if it is pure plumbing."""
    s = text.strip()
    if not s or s.startswith(_NOISE_PREFIXES):
        return ""
    command = _COMMAND.search(s)
    if command and s.startswith(("<command-name>", "<command-message>")):
        args = (command.group("args") or "").strip()
        s = f"{command.group('name').strip()} {args}".strip()
    bash = _BASH_INPUT.fullmatch(s)
    if bash:
        s = f"$ {bash.group(1).strip()}"
    s = _SYSTEM_BLOCK.sub("", s)
    s = _PASTED.sub("", s)
    s = re.sub(r"\n{3,}", "\n\n", s).strip()
    if len(s) > MAX_CHARS:
        s = s[:MAX_CHARS].rstrip() + "\n…[truncated]"
    return s
